def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_d = 0
    for _, o in history:
        if o == 'D':
            opp_d += 1

    if opp_d == 0:
        return 'D'

    if n >= 99:
        return 'D'

    total_c = n - opp_d
    last_me, last_opp = history[-1]

    w = min(12, n)
    recent_d = 0
    for _, o in history[-w:]:
        if o == 'D':
            recent_d += 1
    recent_c = w - recent_d

    chronic = (opp_d >= total_c and recent_d >= recent_c)

    cc = cd = dc = dd = 0
    for i in range(n - 1):
        my = history[i][0]
        nxt = history[i + 1][1]
        if my == 'C':
            if nxt == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if nxt == 'C':
                dc += 1
            else:
                dd += 1

    responsive = (cc + dd) > (cd + dc)

    if last_opp == 'C':
        if last_me == 'D':
            if not chronic and total_c >= 4 * opp_d:
                return 'D'
            if not chronic and total_c >= opp_d and responsive and rng.random() < 0.35:
                return 'D'
            if not chronic and total_c > 3 * opp_d and rng.random() < 0.2:
                return 'D'
            return 'C'

        if not responsive and total_c * 2 <= opp_d * 3:
            return 'D' if rng.random() < 0.75 else 'C'

        if not chronic and total_c >= 8 * opp_d and n >= 90:
            return 'D' if rng.random() < 0.5 else 'C'

        return 'C'

    provoked = (last_me == 'D') or (n >= 2 and history[-2][0] == 'D')

    if provoked:
        if chronic:
            if recent_c >= max(3, w // 2):
                return 'C'
            return 'D'

        if responsive or total_c >= opp_d:
            if recent_d >= 8 and not responsive:
                return 'D' if rng.random() < 0.7 else 'C'
            return 'C'

        return 'D' if rng.random() < 0.8 else 'C'

    if chronic or not responsive:
        return 'D'

    if total_c >= 3 * opp_d and recent_c >= recent_d:
        return 'C' if rng.random() < 0.7 else 'D'

    if total_c > opp_d and recent_c > recent_d:
        return 'C' if rng.random() < 0.4 else 'D'

    return 'D'
